#!/usr/bin/env node
// [INPUT]: design/tokens.json (roles, tiers) and design/icons.json (icon registry + Tabler glyphs).
// [OUTPUT]: the generated files the three clients consume:
//             internal/nativeui/design_gen.go      palette + tiers for the native shell
//             internal/nativeui/icons_gen.go       every native icon var
//             frontend/src/tokens.generated.css    Chat page colour roles, radii, font, icon stroke (+ @media (pointer: coarse) tier)
//             frontend/src/icons.generated.ts      Chat page icon paths
//             <solco-mobile>/src/theme/tokens.generated.ts, icons.generated.ts   the phone's shared roles, radii and icon registry
//             <solco-git>/internal/nativeui/design_gen.go   the same palette and tiers for the sibling Git app (its theme.go / design_system.go are copies of Solco's)
//             <solco-vault>/internal/kit/design_gen.go      the same palette and tiers under package kit, plus the item-type tile colours
// [POS]: the one writer of the design language (docs/product-decisions.md, 2026-11-07 Desktop and phone design language).
//        `node design/gen.mjs` writes; `--check` fails when a generated file has drifted (read-only, CI-safe).
//        The phone repo is found at $SOLCO_MOBILE, the Git app at $SOLCO_GIT and the Vault app at $SOLCO_VAULT, else as siblings; absent, their files are skipped (and said so).
// [PROTOCOL]: 变更时更新此头部，然后检查 CLAUDE.md
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const tokens = JSON.parse(fs.readFileSync(path.join(root, 'design/tokens.json'), 'utf8'));
const iconData = JSON.parse(fs.readFileSync(path.join(root, 'design/icons.json'), 'utf8'));

const HEADER = 'Generated by design/gen.mjs from design/tokens.json and design/icons.json. DO NOT EDIT: change the source and run `node design/gen.mjs`.';

// ---------------------------------------------------------------- colour maths

function parseColor(c) {
  const hex = /^#([0-9a-f]{6})$/i.exec(c);
  if (hex) {
    const n = parseInt(hex[1], 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255, a: 1 };
  }
  const m = /^rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)$/.exec(c);
  if (!m) throw new Error(`unparseable colour ${c}`);
  return { r: +m[1], g: +m[2], b: +m[3], a: +m[4] };
}
const toHex = ({ r, g, b }) => '#' + [r, g, b].map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
/** `top` laid over `base` at `amount` of top. */
function mix(base, top, amount) {
  const a = parseColor(base);
  const b = parseColor(top);
  return toHex({ r: a.r + (b.r - a.r) * amount, g: a.g + (b.g - a.g) * amount, b: a.b + (b.b - a.b) * amount });
}

/** The roles plus the faces derived from them (opaque hover/pressed surfaces, accent states, focus ring). */
function derive(theme, dark) {
  const r = tokens.roles[theme];
  const ink = dark ? '#ffffff' : '#000000';
  const accent = parseColor(r.accent);
  return {
    ...r,
    surfaceHover: mix(r.surface, ink, 0.06),
    surfacePressed: mix(r.surface, ink, 0.11),
    accentHover: dark ? mix(r.accent, '#ffffff', 0.12) : mix(r.accent, '#000000', 0.1),
    accentPressed: dark ? mix(r.accent, '#000000', 0.18) : mix(r.accent, '#000000', 0.22),
    focus: `rgba(${accent.r},${accent.g},${accent.b},${dark ? 0.5 : 0.45})`,
  };
}
const dark = derive('dark', true);
const light = derive('light', false);
const roleNames = Object.keys(dark);

const pascal = (s) => s[0].toUpperCase() + s.slice(1);

// -------------------------------------------------------------------------- Go

function goColor(c) {
  const p = parseColor(c);
  if (p.a === 1 && c.startsWith('#')) return `ui.Hex("${c.toLowerCase()}")`;
  return `ui.RGBA(${p.r}, ${p.g}, ${p.b}, ${p.a})`;
}

function tier(list, role, side) {
  const row = list.find((x) => x.role === role);
  if (!row) throw new Error(`tier role ${role} missing`);
  return row[side];
}

function goDesign(pkg = 'nativeui') {
  const fields = roleNames.map((n) => `\t${pascal(n)} ui.Color`).join('\n');
  const body = (p) => roleNames.map((n) => `\t\t${pascal(n)}: ${goColor(p[n])},`).join('\n');
  const T = (role, side = 'pointer') => tier(tokens.type, role, side).size;
  const S = tokens.space.pointer;
  const R = (role) => tier(tokens.shape, role, 'pointer');
  const C = (role) => tier(tokens.control, role, 'pointer');
  return `// ${HEADER}

package ${pkg}

import "github.com/egoist/mygo/ui"

// designPalette is the unified colour role table (design/tokens.json) of one
// appearance, plus the faces derived from it. Every client draws from these
// names; the native shell maps them onto its theme in theme.go.
type designPalette struct {
${fields}
}

func designRoles(dark bool) designPalette {
\tif dark {
\t\treturn designPalette{
${body(dark)}
\t\t}
\t}
\treturn designPalette{
${body(light)}
\t}
}

// The pointer tier of the type, space, radius and control tables.
var (
\tdesignType = TypographyTokens{
\t\tTitle:     ${T('title')},
\t\tHeading:   ${T('heading')},
\t\tSection:   ${T('section')},
\t\tBody:      ${T('body')},
\t\tBodySmall: ${T('small')},
\t\tCaption:   ${T('small')},
\t\tMicro:     ${T('caption')},
\t}
\tdesignSpace  = SpaceTokens{XXS: ${S[0]}, XS: ${S[1]}, S: ${S[2]}, M: ${S[3]}, L: ${S[4]}, XL: ${S[5]}}
\tdesignRadius = RadiusTokens{Control: ${R('control')}, Row: ${R('row')}, Card: ${R('card')}, Pill: ${R('pill')}}
)

// designControl is the pointer tier of the control heights and the glyph box.
const (
\tdesignControlCompact = ${C('compact')}
\tdesignControlRegular = ${C('regular')}
\tdesignControlRow     = ${C('row')}
\tdesignControlIcon    = ${C('icon')}
)
`;
}

/** The Vault kit's file: the same palette and tiers under package kit, plus the item-type tile colours. */
function vaultDesign() {
  const names = Object.keys(tokens.tiles.light);
  const fields = names.map((n) => `\t${pascal(n)} ui.Color`).join('\n');
  const body = (side) => names.map((n) => `\t\t${pascal(n)}: ${goColor(tokens.tiles[side][n])},`).join('\n');
  return `${goDesign('kit').trimEnd()}

// tilePalette is the item-type tile colours of one appearance (design/tokens.json "tiles"): a solid rounded square under a white glyph.
type tilePalette struct {
${fields}
}

func tileRoles(dark bool) tilePalette {
\tif dark {
\t\treturn tilePalette{
${body('dark')}
\t\t}
\t}
\treturn tilePalette{
${body('light')}
\t}
}
`;
}

function goIcons() {
  const lines = [];
  for (const i of iconData.icons) {
    const g = iconData.glyphs[i.tabler];
    if (!g) throw new Error(`icon ${i.id}: no glyph for ${i.tabler}`);
    for (const name of i.go) lines.push(`\t${name} = icon(\`${g.outline}\`) // ${i.id}`);
  }
  return `// ${HEADER}

package nativeui

// Every native icon var: Tabler outline glyphs drawn by icon() (icons.go) at the
// one desktop stroke. A var belongs to exactly one registry id.
var (
${lines.join('\n')}
)
`;
}

function gofmt(src) {
  return execFileSync('gofmt', [], { input: src, encoding: 'utf8' });
}

// ------------------------------------------------------------------------- CSS

function cssVars(p, indent = '  ') {
  return Object.entries(tokens.cssAliases)
    .map(([name, role]) => `${indent}--${name}: ${p[role]};`)
    .join('\n');
}

function css() {
  const shapeVars = (side) =>
    tokens.shape.map((s) => `  --r-${s.role}: ${s[side]}px;`).join('\n');
  const fontLine = (list) => list.join(', ');
  return `/* ${HEADER}
   One role table for the desktop Chat page and the phone: the colours, the
   radii, the UI face and the icon stroke. The pointer tier is the default; a
   touch screen (the phone) takes the @media (pointer: coarse) tier. */

:root {
${cssVars(light)}
${shapeVars('pointer')}
  --ff-ui: ${fontLine(tokens.fonts.pointer)};
  --icon-stroke: ${iconData.stroke.pointer};
}

:root[data-theme="dark"] {
${cssVars(dark)}
}

@media (pointer: coarse) {
  :root {
${tokens.shape.map((s) => `    --r-${s.role}: ${s.touch}px;`).join('\n')}
    --ff-ui: ${fontLine(tokens.fonts.touch)};
    --icon-stroke: ${iconData.stroke.touch};
  }
}
`;
}

function chatIcons() {
  const lines = [];
  for (const i of iconData.icons) {
    for (const key of i.chat) lines.push(`  ${key}: '${iconData.glyphs[i.tabler].outline}', // ${i.id}`);
  }
  return `// ${HEADER}
// The Chat page's icon paths: Tabler outline glyphs, one per registry id, keyed by the page's own names.
export const PATHS = {
${lines.join('\n')}
} as const;
`;
}

// ----------------------------------------------------------------------- phone

function phoneTokens() {
  const hexRoles = ['chrome', 'canvas', 'surface', 'raised', 'grouped', 'user', 'line', 'lineStrong', 'text', 'muted', 'accent', 'accentText', 'accentSoft', 'onAccent', 'ok', 'okSoft', 'warn', 'warnSoft', 'danger', 'dangerSoft', 'scrim'];
  const block = (name, r) => `export const ${name} = {\n${hexRoles.map((n) => `  ${n}: '${r[n]}',`).join('\n')}\n} as const;\n`;
  const shape = tokens.shape.map((s) => `  ${s.role}: ${s.touch},`);
  return `// ${HEADER}
// The roles and the touch radius tier the phone shares with the desktop, one table per appearance; theme/tokens.ts spells its own names over them.
${block('rolesDark', dark)}
${block('rolesLight', light)}
export const touchShape = {
${shape.join('\n')}
} as const;
`;
}

function phoneIcons() {
  const lines = iconData.icons.map((i) => `  '${i.id}': { tabler: '${i.tabler}', filled: ${i.filled} },`);
  return `// ${HEADER}
// The icon registry as the phone sees it: a product meaning (id) and its Tabler glyph; \`filled\` marks the ids that draw the filled variant when active.
export const iconRegistry = {
${lines.join('\n')}
} as const;
`;
}

// ---------------------------------------------------------------------- output

function findSibling(envName, name, marker) {
  const candidates = [process.env[envName], path.resolve(root, '..', name), path.resolve(root, '../..', name)].filter(Boolean);
  return candidates.find((c) => fs.existsSync(path.join(c, marker)));
}

const outputs = [
  ['internal/nativeui/design_gen.go', gofmt(goDesign())],
  ['internal/nativeui/icons_gen.go', gofmt(goIcons())],
  ['frontend/src/tokens.generated.css', css()],
  ['frontend/src/icons.generated.ts', chatIcons()],
];
const mobile = findSibling('SOLCO_MOBILE', 'solco-mobile', 'package.json');
const git = findSibling('SOLCO_GIT', 'solco-git', 'mygo.config.ts');
const vaultApp = findSibling('SOLCO_VAULT', 'solco-vault', 'mygo.config.ts');
if (mobile) {
  outputs.push([path.join(mobile, 'src/theme/tokens.generated.ts'), phoneTokens()], [path.join(mobile, 'src/theme/icons.generated.ts'), phoneIcons()]);
} else {
  console.warn('design/gen.mjs: solco-mobile not found (set SOLCO_MOBILE); its generated files are skipped');
}
if (git) {
  outputs.push([path.join(git, 'internal/nativeui/design_gen.go'), outputs[0][1]]);
} else {
  console.warn('design/gen.mjs: solco-git not found (set SOLCO_GIT); its generated file is skipped');
}

if (vaultApp) {
  outputs.push([path.join(vaultApp, 'internal/kit/design_gen.go'), gofmt(vaultDesign())]);
} else {
  console.warn('design/gen.mjs: solco-vault not found (set SOLCO_VAULT); its generated file is skipped');
}

let drift = 0;
for (const [file, content] of outputs) {
  const abs = path.isAbsolute(file) ? file : path.join(root, file);
  const current = fs.existsSync(abs) ? fs.readFileSync(abs, 'utf8') : null;
  if (check) {
    if (current !== content) {
      drift++;
      console.error(`design/gen.mjs: ${file} is out of date`);
    }
  } else if (current !== content) {
    fs.writeFileSync(abs, content);
    console.log(`wrote ${file}`);
  }
}
if (check && drift) {
  console.error('run `node design/gen.mjs` and commit the result');
  process.exit(1);
}
if (check) console.log(`design/gen.mjs: ${outputs.length} generated files are current`);
